#!/usr/bin/env python3
import pathlib,json
root=pathlib.Path(__file__).resolve().parents[1]
core=(root/'src/core.mjs').read_text().replace('export ','')
gpu=(root/'src/webgpu.mjs').read_text().replace('export ','')
data=(root/'assets/zhou_target.json').read_text()
page=r'''<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>周舒畅 · WebGPU 精度实验室</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#111616;color:#edf2e8;font:15px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1120px;padding:35px;margin:auto}a{color:#c4ef89}h1{font-size:37px;line-height:1.35;margin:20px 0}h2{font-size:20px}.muted,small{color:#a5b3ab}.tag{font:11px monospace;letter-spacing:.1em;color:#c4ef89}.panel{background:#1a2221;border:1px solid #35443e;border-radius:12px;padding:23px;margin-top:22px}.controls{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}label{font-size:12px;color:#a5b3ab}select{display:block;width:100%;background:#111616;border:1px solid #35443e;color:#edf2e8;padding:8px;margin-top:5px;border-radius:5px}button{background:#c4ef89;border:0;border-radius:6px;padding:11px 18px;margin:18px 8px 0 0;cursor:pointer;color:#152310}button:disabled{opacity:.45;cursor:default}.secondary{background:transparent;color:#c4ef89;border:1px solid #35443e}.images{display:grid;grid-template-columns:1fr 1fr;gap:20px}canvas{display:block;width:100%;background:black;image-rendering:pixelated;border-radius:5px}.images p{font-size:12px;color:#a5b3ab}.stats{display:flex;flex-wrap:wrap;gap:28px;font-size:12px;color:#a5b3ab}.stats b{display:block;color:#c4ef89;font:24px monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 monospace;background:#0c1110;padding:18px;border-radius:7px;max-height:400px;overflow:auto}table{width:100%;font-size:12px;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #35443e}#status{color:#c4ef89}ul{font-size:13px;color:#a5b3ab}#error{color:#ffb77f;white-space:pre-wrap}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:750px){main{padding:20px}.controls{grid-template-columns:1fr 1fr}.images,.columns{grid-template-columns:1fr}h1{font-size:29px}}
</style><main><a href="report.html">← 返回实测报告</a><p class="tag">WEBGPU COMPUTE / MIXED PRECISION / LOCAL ONLY</p>
<h1>把“周舒畅”交给浏览器 GPU。</h1><p class="muted">这是实际的 WebGPU compute shader，不是远程 CUDA。FP16 模式会改变数值与轨迹，下面可测速度、内存与最终图像误差。所有计算留在本机。</p>
<div class="panel"><h2>设备与能力</h2><p id="capability">正在检测 WebGPU…</p><small>如果 file:// 下不可用，请在本目录运行 python3 -m http.server 8766，再用浏览器打开 http://localhost:8766/webgpu_lab.html。</small></div>
<div class="panel"><div class="controls">
<label>计算精度<select id="precision"><option value="fp32">FP32 参考</option><option value="f16-cache" selected>FP16 缓存 / FP32 计算</option><option value="f16-exp">FP16 缓存 + exp</option></select></label>
<label>分辨率<select id="resolution"><option value="160">160 × 64</option><option value="320" selected>320 × 128</option></select></label>
<label>高斯数量<select id="gaussians"><option>128</option><option>400</option><option selected>800</option></select></label>
<label>独立链<select id="chains"><option selected>1</option><option>4</option><option>8</option><option>16</option></select></label>
<label>每链迭代<select id="iterations"><option value="8192">8,192 · 检查</option><option value="65536" selected>65,536</option><option value="262144">262,144</option><option value="524288">524,288</option></select></label></div>
<button id="run">开始 WebGPU 拟合</button><button id="stop" class="secondary" disabled>停止并保留结果</button><button id="compare" class="secondary">三种精度对比基准</button><button id="export" class="secondary" disabled>下载运行数据 JSON</button>
<p id="status">准备就绪</p><p id="error"></p><p class="muted" style="font-size:12px">笔画加权初始化；温度 2 → 0.001，提案幅度随温度缩小。每 8,192 步重新计算贡献缓存。支持 800 个高斯，但多链贡献矩阵可能超过浏览器单缓冲限制；会明确报错。</p></div>
<div class="panel"><div class="images"><div><p>目标 · STHeiti Medium · 抗锯齿灰度</p><canvas id="target" width="320" height="128"></canvas></div><div><p>当前拟合 · 最低缓存 MSE 的链</p><canvas id="result" width="320" height="128"></canvas></div></div><div class="stats"><span>迭代<b id="iteration">0</b></span><span>缓存 MSE<b id="loss">—</b></span><span>GPU 时间<b id="gpu-time">—</b></span><span>墙钟时间<b id="wall-time">—</b></span><span>贡献矩阵<b id="memory">—</b></span></div></div>
<div class="panel"><h2>可复现的精度对比</h2><p class="muted">固定 160×64、128 高斯、4 条链、每链 8,192 步，各模式预热后跑 3 次，顺序轮换。GPU timestamp 可用时单独报告 kernel 时间；墙钟包含进度回传。最终参数统一用 JS Float64 完整重渲染，评估不同近似轨迹的实际质量。</p><div style="overflow:auto"><table><thead><tr><th>模式</th><th>GPU 中位数 ms</th><th>墙钟 ms</th><th>完整重渲染 MSE</th><th>缓存/重渲染图像 MAE</th><th>缓存 MiB</th></tr></thead><tbody id="bench-table"></tbody></table></div>
<p class="muted" style="font-size:12px">这不是“相同接受轨迹”的精度验证。FP16 改变贡献及 exp，从而可能改变接受决策；不能把质量损失隐藏在加速数字里。总和与坐标保持 FP32，SSE 用 u32；本原型最多 65,536 像素以避免 SSE 溢出。</p><pre id="evidence">尚未运行</pre></div>
<div class="columns"><div class="panel"><h2>已实现的网页加速</h2><ul><li>状态常驻 GPU，每个 workgroup 拥有一条顺序链。</li><li>64 步在一次 dispatch 内完成，一次提交合并 1,024 步。</li><li>缓存贡献，拒绝提案不重算全图；只定期回传图像和状态。</li><li>FP16 缓存降低贡献矩阵和候选缓冲内存一半，计算与总和保留 FP32。</li><li>可选 FP16 exp / 幅度相乘，对比是否真的更快。</li></ul></div><div class="panel"><h2>为什么不是直接全部 BF16 / FP16</h2><ul><li>WGSL 原生支持可选 f16，没有标准 bf16 标量。BF16 位打包仿真不能据此宣称硬件算术加速。</li><li>贡献幅度通常不超过 255，FP16 的 10 位显式尾数比 BF16 的 7 位更适合这里。</li><li>总和、位置差平方、损失累加全用半精度容易溢出或破坏取整边界。</li><li>没有 GEMM，因此没有自动用上 Tensor Core；主要瓶颈仍可能是 exp、同步和并行度。</li></ul><small><a href="https://www.w3.org/TR/WGSL/">WGSL 标准</a> · <a href="https://developer.chrome.com/blog/new-in-webgpu-120">shader-f16 使用方式</a></small></div></div>
</main><script type="module">
__CORE__
__GPU__
const TARGET=__TARGET__;
const $=id=>document.getElementById(id);
function draw(id,data,W,H){const c=$(id);c.width=W;c.height=H;const ctx=c.getContext('2d'),im=ctx.createImageData(W,H);data.forEach((v,i)=>{im.data[4*i]=im.data[4*i+1]=im.data[4*i+2]=v;im.data[4*i+3]=255;});ctx.putImageData(im,0,0);}
draw('target',TARGET.pixels,320,128);draw('result',new Uint8Array(40960),320,128);
function input(width){if(width===320)return Uint8Array.from(TARGET.pixels);const c=document.createElement('canvas');c.width=160;c.height=64;const x=c.getContext('2d');const full=document.createElement('canvas');full.width=320;full.height=128;const fc=full.getContext('2d'),im=fc.createImageData(320,128);TARGET.pixels.forEach((v,i)=>{im.data[4*i]=im.data[4*i+1]=im.data[4*i+2]=v;im.data[4*i+3]=255;});fc.putImageData(im,0,0);x.drawImage(full,0,0,160,64);const a=x.getImageData(0,0,160,64).data;return Uint8Array.from({length:10240},(_,p)=>a[4*p]);}
let engine=null,last=null,benchResults=[],busy=false;
function buttons(on){busy=on;$('run').disabled=on;$('compare').disabled=on;$('stop').disabled=!on;}
function show(r){last=r;draw('result',r.image,r.W,r.H);$('iteration').textContent=r.iteration.toLocaleString();$('loss').textContent=r.loss.toFixed(2);$('gpu-time').textContent=r.gpu_ms===null?'不支持 timestamp':(r.gpu_ms/1000).toFixed(3)+' s';$('wall-time').textContent=(r.wall_ms/1000).toFixed(3)+' s';$('memory').textContent=(r.cache_bytes/1048576).toFixed(1)+' MiB';}
function validate(r,t){
 const gs=Array.from({length:r.N},(_,j)=>{const a=r.gaussians.slice(j*8,j*8+8);return {x:a[0],y:a[1],scaleX:a[2],scaleY:a[3],rotation:a[4],opacity:a[5]};});
 const c=new CachedChain(gs,r.W,r.H,t),ref=c.image();let mae=0,max=0;
 for(let p=0;p<ref.length;p++){const e=Math.abs(ref[p]-r.image[p]);mae+=e;max=Math.max(max,e);}
 return {...r,rerender_loss:c.loss,render_mae:mae/ref.length,render_max_error:max,psnr:10*Math.log10(255*255/c.loss)};
}
async function one(mode,W,N,C,steps,progress=true){engine=await WebGPUFit.create(mode);const t=input(W);draw('target',t,W,W*2/5);try{return await engine.run(t,W,W*2/5,N,C,steps,progress?r=>show(r):()=>{});}finally{engine.destroy();engine=null;}}
$('run').onclick=async()=>{buttons(true);$('error').textContent='';$('status').textContent='编译 shader 并初始化…';try{const W=Number($('resolution').value),r=await one($('precision').value,W,Number($('gaussians').value),Number($('chains').value),Number($('iterations').value));last=validate(r,input(W));show(last);$('evidence').textContent=JSON.stringify({...last,image:undefined,gaussians:undefined},null,2);$('status').textContent='完成；统一 Float64 重渲染 MSE '+last.rerender_loss.toFixed(3)+', PSNR '+last.psnr.toFixed(2)+' dB';$('export').disabled=false;}catch(e){$('error').textContent=e.stack||e.message;$('status').textContent='运行未完成，错误已展示。';}finally{buttons(false);}};
$('stop').onclick=()=>{if(engine)engine.cancelled=true;$('status').textContent='将在当前 1,024 步批次结束后停止。';};
$('compare').onclick=async()=>{buttons(true);$('error').textContent='';benchResults=[];$('bench-table').textContent='';try{const modes=['fp32','f16-cache','f16-exp'];for(const mode of modes){$('status').textContent='预热 '+mode;await one(mode,160,128,4,1024,false);}for(let repeat=0;repeat<3;repeat++){for(let k=0;k<3;k++){const mode=modes[(k+repeat)%3];$('status').textContent='基准 '+mode+' / 第 '+(repeat+1)+' 轮';let r=await one(mode,160,128,4,8192,false);r=validate(r,input(160));benchResults.push({...r,repeat,image:undefined,gaussians:undefined});show(r);$('evidence').textContent=JSON.stringify(benchResults,null,2);}}const median=v=>[...v].sort((a,b)=>a-b)[1];for(const mode of modes){const rs=benchResults.filter(r=>r.mode===mode),r=rs[0],tr=document.createElement('tr');[mode,r.gpu_ms===null?'不可用':median(rs.map(r=>r.gpu_ms)).toFixed(2),median(rs.map(r=>r.wall_ms)).toFixed(2),r.rerender_loss.toFixed(3),r.render_mae.toFixed(4),(r.cache_bytes/1048576).toFixed(1)].forEach(t=>{const td=document.createElement('td');td.textContent=t;tr.append(td);});$('bench-table').append(tr);}$('status').textContent='三种精度、各3轮完成。请同时比较速度和质量。';$('export').disabled=false;}catch(e){$('error').textContent=e.stack||e.message;$('status').textContent='基准未完成。已完成记录保留。';}finally{buttons(false);}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(benchResults.length?benchResults:last,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='webgpu_results.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);};
(async()=>{try{if(!navigator.gpu)throw Error('navigator.gpu 不可用');const a=await navigator.gpu.requestAdapter();if(!a)throw Error('无可用 adapter');$('capability').textContent=JSON.stringify({adapter:a.info?{vendor:a.info.vendor,architecture:a.info.architecture,device:a.info.device,description:a.info.description}:null,shader_f16:a.features.has('shader-f16'),timestamp_query:a.features.has('timestamp-query'),maxStorageBufferMiB:a.limits.maxStorageBufferBindingSize/1048576});}catch(e){$('capability').textContent='WebGPU 不可用：'+e.message;}})();
</script></html>'''
page=page.replace('__CORE__',core).replace('__GPU__',gpu).replace('__TARGET__',data)
(root/'webgpu_lab.html').write_text(page)
print('webgpu_lab.html',len(page.encode()),'bytes')

